Add-Type -AssemblyName System.Drawing; $dir = Get-ChildItem 'C:\Users\Jerry-Huang\Desktop' -Directory | Where-Object { $_.Name -match '图片' } | Select-Object -First 1; Write-Host ('found=' + $dir.Name); $src = Get-ChildItem $dir.FullName -Filter *.png | Select-Object -First 1; Write-Host ('src=' + $src.Name); $bmp = [System.Drawing.Bitmap]::FromFile($src.FullName); if ($bmp.Width -gt 1600) { $nw = 1600; $nh = [int]($bmp.Height * $nw / $bmp.Width); $nb = New-Object System.Drawing.Bitmap($nw, $nh); $g = [System.Drawing.Graphics]::FromImage($nb); $g.DrawImage($bmp, 0, 0, $nw, $nh); $nb.Save('D:\Rust\steel-front\screenshots\launcher_issue.png', [System.Drawing.Imaging.ImageFormat]::Png); $g.Dispose(); $nb.Dispose(); Write-Host 'resized' } else { Copy-Item $src.FullName 'D:\Rust\steel-front\screenshots\launcher_issue.png' -Force; Write-Host 'copied' }; $bmp.Dispose()